    {'ll': [-90.0751, 29.9546], 'label': 'New Orleans', 'date': 'Plessy 1896; constitution 1898', 'acc': True, 'big': True, 'dy': 16, 'plate': {'kicker': 'US5.7 · Louisiana', 'title': 'Plessy and the 1898 constitution', 'sub': '1896 and 1898', 'text': "[[c-us5-jc-plessy]] [[c-us5-jc-harlan]] [[c-us5-jc-la1898]]", 'sources': ['us5b-plessy', 'us5b-64p-1898']}},
